import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

custom_matmul_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void matmul_kernel(const float* A, const float* B, float* C, int M, int N, int K) {
    extern __shared__ float A_row[];

    int row = blockIdx.x;
    int col = blockIdx.y * blockDim.x + threadIdx.x;

    if (row >= M || col >= N) return;

    // Load entire row of A into shared memory
    if (threadIdx.x < K) {
        A_row[threadIdx.x] = A[row * K + threadIdx.x];
    }
    __syncthreads();

    float sum = 0.0f;
    for (int k = 0; k < K; k++) {
        sum += A_row[k] * B[k * N + col];
    }

    C[row * N + col] = sum;
}

torch::Tensor custom_matmul_cuda(torch::Tensor A, torch::Tensor B) {
    int M = A.size(0);
    int K = A.size(1);
    int N = B.size(1);

    auto C = torch::zeros({M, N}, A.options());

    const int block_size = 256;
    dim3 grid(M, (N + block_size - 1) / block_size);
    dim3 block(block_size);

    size_t shared_mem = K * sizeof(float);

    matmul_kernel<<<grid, block, shared_mem>>>(
        A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(), M, N, K
    );

    return C;
}
"""

custom_matmul_cpp_source = "torch::Tensor custom_matmul_cuda(torch::Tensor A, torch::Tensor B);"

custom_matmul = load_inline(
    name='custom_matmul',
    cpp_sources=custom_matmul_cpp_source,
    cuda_sources=custom_matmul_source,
    functions=['custom_matmul_cuda'],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()
        self.custom_matmul = custom_matmul

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return self.custom_matmul.custom_matmul_cuda(A, B)
